use vstd::prelude::*;

verus! {

    // A pure specification of right‐rotating a non‐empty sequence `list` by `n` positions.
    spec fn rotate_spec(list: Seq<u32>, n: nat) -> Seq<u32>
        requires
            list.len() > 0
    {
        let len = list.len();
        let k = n % len;       // effective rotation to the right
        let s = len - k;       // split point: suffix starts at index s
        // result is suffix(list, s..len) followed by prefix(list, 0..s)
        list.slice(s, len) + list.slice(0, s)
    }

    // Implements right-rotation of a non‐empty Vec<u32> by n mod len positions.
    fn rotate_right(list: &Vec<u32>, n: usize) -> (new_list: Vec<u32>)
        requires
            list.len() > 0
        ensures
            new_list.len() == list.len(),
            new_list@ == rotate_spec(list@, n as nat)
    {
        let len = list.len();
        let k = n % len;         // rotation amount mod length
        let s = len - k;         // starting index of the suffix
        // Remember the spec result for use in invariants
        let spec_seq = rotate_spec(list@, n as nat);

        // Build the result in two phases:
        //   1. push the suffix list[s..len]
        //   2. push the prefix list[0..s]
        let mut res: Vec<u32> = Vec::with_capacity(len);

        // Phase 1: copy list[i] for i in [s, len)
        let mut i = s;
        while i < len
            invariant
                s <= i && i <= len,
                res.len() == i - s,
                // res@ equals the first (i - s) elements of the spec rotation
                res@ == spec_seq.slice(0, i - s),
            decreases len - i
        {
            res.push(list[i]);
            i += 1;
        }

        // Phase 2: copy list[j] for j in [0, s)
        let mut j = 0;
        while j < s
            invariant
                0 <= j && j <= s,
                res.len() == (len - s) + j,
                // res@ equals the first ((len - s) + j) elements of the spec rotation
                res@ == spec_seq.slice(0, (len - s) + j),
            decreases s - j
        {
            res.push(list[j]);
            j += 1;
        }

        res
    }

}

